'use client'

import * as React from 'react'

import { useInViewOnce } from './use-reduced-motion'
import './wipe-reveal.css'

type WipeTag = 'p' | 'span' | 'div' | 'h1' | 'h2' | 'h3' | 'h4'

export type WipeRevealProps = {
    children: React.ReactNode
    as?: WipeTag
    /** Colour of the wiping bar. */
    color?: string
    /** Milliseconds for the whole wipe. */
    duration?: number
    delay?: number
    className?: string
}

// Editorial wipe: a bar sweeps across and leaves the text behind it. The text is
// real and always in the accessibility tree; only its clip animates.
const WipeReveal = ({ children, as: Tag = 'span', color = '#a78bfa', duration = 900, delay = 0, className }: WipeRevealProps) => {
    const ref = React.useRef<HTMLElement | null>(null)
    const [shown, setShown] = React.useState(false)
    useInViewOnce(ref, () => setShown(true), !shown, 0.5)

    return <Tag
        ref={ref as React.Ref<never>}
        className={['rad-fx-wipe', className].filter(Boolean).join(' ')}
        data-state={shown ? 'shown' : 'hidden'}
        style={{ '--rad-fx-wipe-color': color, '--rad-fx-wipe-duration': `${duration}ms`, '--rad-fx-wipe-delay': `${delay}ms` } as React.CSSProperties}
    >
        <span className="rad-fx-wipe-text">{children}</span>
        <span className="rad-fx-wipe-bar" aria-hidden="true" />
    </Tag>
}

export default WipeReveal

.rad-fx-wipe {
    position: relative;
    display: inline-block;
}

.rad-fx-wipe-text {
    display: inline-block;
    clip-path: inset(0 100% 0 0);
}

.rad-fx-wipe[data-state='shown'] .rad-fx-wipe-text {
    animation: rad-fx-wipe-text var(--rad-fx-wipe-duration, 900ms) var(--rad-fx-wipe-delay, 0ms) both;
}

.rad-fx-wipe-bar {
    position: absolute;
    inset: 0;
    background: var(--rad-fx-wipe-color);
    transform: scaleX(0);
    transform-origin: 0 50%;
    pointer-events: none;
}

.rad-fx-wipe[data-state='shown'] .rad-fx-wipe-bar {
    animation: rad-fx-wipe-bar var(--rad-fx-wipe-duration, 900ms) cubic-bezier(0.7, 0, 0.3, 1) var(--rad-fx-wipe-delay, 0ms) both;
}

/* The bar grows to cover the text, the text is revealed under it, then the bar exits right. */
@keyframes rad-fx-wipe-bar {
    0% { transform: scaleX(0); transform-origin: 0 50%; }
    50% { transform: scaleX(1); transform-origin: 0 50%; }
    50.1% { transform: scaleX(1); transform-origin: 100% 50%; }
    100% { transform: scaleX(0); transform-origin: 100% 50%; }
}

@keyframes rad-fx-wipe-text {
    0%, 49.9% { clip-path: inset(0 100% 0 0); }
    50%, 100% { clip-path: inset(0 0 0 0); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-wipe-text, .rad-fx-wipe[data-state] .rad-fx-wipe-text { clip-path: none; animation: none; }
    .rad-fx-wipe-bar, .rad-fx-wipe[data-state] .rad-fx-wipe-bar { display: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-wipe-text { clip-path: none; animation: none !important; }
[data-rad-fx-motion='reduce'] .rad-fx-wipe-bar { display: none; }
